function robotWithString(s) {
  const n = s.length;
  const suffixMin = new Array(n + 1).fill('{');
  for (let i = n - 1; i >= 0; i--) {
    suffixMin[i] = s[i] < suffixMin[i + 1] ? s[i] : suffixMin[i + 1];
  }

  const stack = [];
  const paper = [];
  for (let i = 0; i < n; i++) {
    stack.push(s[i]);
    while (stack.length > 0 && stack[stack.length - 1] <= suffixMin[i + 1]) {
      paper.push(stack.pop());
    }
  }
  return paper.join('');
}

