function robotWithString(s) {
  // Try every legal sequence of moves and keep the smallest written string.
  let answer = null;
  const explore = (index, held, written) => {
    if (index === s.length && held.length === 0) {
      if (answer === null || written < answer) answer = written;
      return;
    }
    if (index < s.length) explore(index + 1, held + s[index], written);
    if (held.length > 0) explore(index, held.slice(0, -1), written + held[held.length - 1]);
  };
  explore(0, '', '');
  return answer;
}

