function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 9);
  const choices = [2, 3, 5, 26];
  const letters = choices[Math.floor(rand() * choices.length)];
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  return [s];
}
